  'DRAFT','REQUESTED','AWAITING_SUPERVISOR','READY','ACTIVE','STOP_CANDIDATE','ENDED',
  'AWAITING_LEARNER_REFLECTION','AWAITING_ADULT_REVIEW','RETURNED_FOR_REVISION','APPROVED','VOIDED','RECOVERY_REQUIRED'
);
