-- ===== supabase/migrations/0005_devices_vehicles.sql =====
-- 0005 Devices (GPS sources, no hardware identifiers) and vehicles
create table public.devices (
  id uuid primary key default gen_random_uuid(),
  owner_user_id uuid not null references public.profiles (id) on delete cascade,
  anonymous_device_key text not null,
  platform text not null default 'unknown',
  label text not null default '',
  last_seen_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  unique (owner_user_id, anonymous_device_key)
);

create or replace function app.register_device(p_key text, p_platform text, p_label text default '')
returns uuid language plpgsql security definer set search_path = public, app, extensions as $$
declare v_id uuid; v_uid uuid := app.uid();
begin
  if v_uid is null then perform app.fail('UNAUTHENTICATED', 'Sign in required'); end if;
  if length(p_key) < 16 or length(p_key) > 128 then perform app.fail('VALIDATION', 'Invalid device key'); end if;
  insert into public.devices (owner_user_id, anonymous_device_key, platform, label)
  values (v_uid, p_key, left(coalesce(p_platform, 'unknown'), 40), left(coalesce(p_label, ''), 60))
  on conflict (owner_user_id, anonymous_device_key)
  do update set last_seen_at = now(), platform = excluded.platform
  returning id into v_id;
  return v_id;
end $$;

create table public.vehicles (
  id uuid primary key default gen_random_uuid(),
  learner_id uuid not null references public.profiles (id) on delete cascade,
  label text not null check (length(label) between 1 and 60),
  created_at timestamptz not null default now(),
  archived_at timestamptz
);
create index vehicles_learner_idx on public.vehicles (learner_id);

-- ===== supabase/migrations/0006_drive_sessions.sql =====
-- 0006 Drive sessions, participants, session devices
create table public.drive_sessions (
  id uuid primary key default gen_random_uuid(),
  learner_id uuid not null references public.profiles (id) on delete cascade,
  supervisor_id uuid references public.profiles (id),
  controller_user_id uuid references public.profiles (id),
  primary_recorder_device_id uuid references public.devices (id),
  vehicle_id uuid references public.vehicles (id),
  session_type public.session_type not null default 'FAMILY_SUPERVISED',
  evidence_type public.evidence_type not null default 'GPS',
  status public.session_status not null default 'DRAFT',
  jurisdiction text not null,
  ruleset_version text not null,
  timezone text not null default 'America/Los_Angeles',
  supervisor_present boolean not null default true,
  planned_skill_ids uuid[] not null default '{}',
  requested_at timestamptz,
  accepted_at timestamptz,
  server_started_at timestamptz,
  server_ended_at timestamptz,
  ended_by uuid,
  end_override_reason text,
  gps_incomplete boolean not null default false,
  proposed_duration_minutes integer,
  credited_duration_minutes integer,
  proposed_night_minutes integer not null default 0,
  credited_night_minutes integer not null default 0,
  night_gap_minutes integer not null default 0,
  distance_meters integer,
  gps_quality public.gps_quality,
  processing_version text,
  night_algorithm_version text,
  processing_error text,
  -- Manual / professional records
  manual_started_at timestamptz,
  manual_ended_at timestamptz,
  school_name text,
  instructor_name text,
  learner_note text,
  created_by uuid references public.profiles (id),
  start_idempotency_key text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (credited_night_minutes <= coalesce(credited_duration_minutes, 2147483647)),
  check (session_type <> 'PROFESSIONAL_INSTRUCTION' or evidence_type = 'ATTESTED')
);
create index drive_sessions_learner_idx on public.drive_sessions (learner_id, created_at desc);
create index drive_sessions_supervisor_idx on public.drive_sessions (supervisor_id, status);
create unique index drive_sessions_one_live_per_learner on public.drive_sessions (learner_id)
  where status in ('REQUESTED','AWAITING_SUPERVISOR','READY','ACTIVE','STOP_CANDIDATE');
create unique index drive_sessions_start_idempotency on public.drive_sessions (learner_id, start_idempotency_key)
  where start_idempotency_key is not null;
create trigger drive_sessions_updated before update on public.drive_sessions for each row execute function app.set_updated_at();

create table public.session_participants (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.drive_sessions (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  role public.participant_role not null,
  physically_in_vehicle boolean not null default false,
  can_view_live boolean not null default false,
  can_observe boolean not null default false,
  joined_at timestamptz not null default now(),
  left_at timestamptz,
  unique (session_id, user_id)
);
create index session_participants_user_idx on public.session_participants (user_id);

create table public.session_devices (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.drive_sessions (id) on delete cascade,
  device_id uuid not null references public.devices (id),
  owner_user_id uuid not null references public.profiles (id),
  is_recorder boolean not null default false,
  location_permission text not null default 'unknown',
  last_sample_at timestamptz,
  connectivity_state public.connectivity_state not null default 'UNKNOWN',
  updated_at timestamptz not null default now(),
  unique (session_id, device_id)
);

create or replace function app.session_live_statuses() returns public.session_status[] language sql immutable as $$
  select array['ACTIVE','STOP_CANDIDATE']::public.session_status[]
$$;

-- Access helpers --------------------------------------------------------------------------
create or replace function app.can_view_session(p_session uuid) returns boolean
language sql stable security definer set search_path = public, app, extensions as $$
  select exists (
    select 1 from public.drive_sessions s
    where s.id = p_session and (s.learner_id = app.uid() or app.is_active_linked_adult(s.learner_id, app.uid()))
  )
$$;

create or replace function app.is_live_participant(p_session uuid) returns boolean
language sql stable security definer set search_path = public, app, extensions as $$
  select exists (
    select 1 from public.session_participants sp join public.drive_sessions s on s.id = sp.session_id
    where sp.session_id = p_session and sp.user_id = app.uid() and sp.left_at is null and sp.can_view_live
      and sp.role in ('IN_CAR_SUPERVISOR','REMOTE_VIEWER')
      and app.is_active_linked_adult(s.learner_id, app.uid())
  )
$$;

create or replace function app.is_in_car_supervisor(p_session uuid) returns boolean
language sql stable security definer set search_path = public, app, extensions as $$
  select exists (
    select 1 from public.session_participants sp join public.drive_sessions s on s.id = sp.session_id
    where sp.session_id = p_session and sp.user_id = app.uid() and sp.left_at is null
      and sp.role = 'IN_CAR_SUPERVISOR' and sp.physically_in_vehicle
      and app.is_active_linked_adult(s.learner_id, app.uid())
  )
$$;

-- ===== supabase/migrations/0007_samples_live_routes.sql =====
-- 0007 Location samples (private raw), live session state (throttled, approximate), processed routes
create table public.location_samples (
  session_id uuid not null references public.drive_sessions (id) on delete cascade,
  device_id uuid not null references public.devices (id),
  sequence_no integer not null check (sequence_no >= 0),
  recorded_at timestamptz not null,
  latitude double precision not null check (latitude between -90 and 90),
  longitude double precision not null check (longitude between -180 and 180),
  accuracy_m real,
  speed_mps real,
  heading_deg real,
  received_at timestamptz not null default now(),
  primary key (session_id, device_id, sequence_no)
);
create index location_samples_session_time_idx on public.location_samples (session_id, recorded_at);

create table public.live_session_state (
  session_id uuid primary key references public.drive_sessions (id) on delete cascade,
  latest_latitude double precision,
  latest_longitude double precision,
  latest_accuracy_m real,
  latest_speed_mps real,
  latest_sample_at timestamptz,
  elapsed_seconds integer not null default 0,
  estimated_distance_m integer not null default 0,
  sample_count integer not null default 0,
  gps_quality public.gps_quality not null default 'NONE',
  recorder_state public.recorder_state not null default 'UNKNOWN',
  connectivity_state public.connectivity_state not null default 'UNKNOWN',
  battery_warning text,
  stationary_since timestamptz,
  updated_at timestamptz not null default now()
);

create table public.drive_routes (
  session_id uuid primary key references public.drive_sessions (id) on delete cascade,
  route_geojson jsonb,
  simplified_geojson jsonb,
  point_count integer not null default 0,
  accepted_point_count integer not null default 0,
  rejection_counts jsonb not null default '{}'::jsonb,
  processing_version text not null,
  processed_at timestamptz not null default now(),
  route_deleted_at timestamptz,
  deleted_by uuid
);

-- PostGIS columns are created only when the extension exists (Supabase); see DECISIONS.md D-003.
do $$ begin
  if exists (select 1 from pg_extension where extname = 'postgis') then
    execute 'alter table public.location_samples add column geog geography(Point, 4326)
             generated always as (ST_SetSRID(ST_MakePoint(longitude, latitude), 4326)::geography) stored';
    execute 'alter table public.drive_routes add column route_geom geography(LineString, 4326)';
  end if;
end $$;

-- ===== supabase/migrations/0008_observations_reflections_reviews.sql =====
-- 0008 In-drive observations (append-only), learner reflections, supervisor reviews, skill tags
create table public.drive_observations (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.drive_sessions (id) on delete cascade,
  author_id uuid not null references public.profiles (id),
  author_role public.participant_role not null,
  skill_id uuid references public.skills (id),
  observation_type public.observation_type not null,
  assessment public.observation_assessment not null default 'NEUTRAL',
  occurred_at timestamptz not null default now(),
  elapsed_seconds integer,
  latitude double precision,
  longitude double precision,
  note text check (note is null or length(note) <= 280),
  verification_level public.verification_level not null default 'UNVERIFIED',
  finalized boolean not null default false,
  finalized_by uuid,
  finalized_at timestamptz,
  learner_visible boolean not null default false,
  client_event_id text,
  created_at timestamptz not null default now(),
  unique (session_id, client_event_id)
);
create index drive_observations_session_idx on public.drive_observations (session_id, occurred_at);

create table public.learner_reflections (
  session_id uuid primary key references public.drive_sessions (id) on delete cascade,
  rating integer check (rating between 1 and 5),
  went_well text check (went_well is null or length(went_well) <= 280),
  improve text check (improve is null or length(improve) <= 280),
  summary text check (summary is null or length(summary) <= 500),
  confidence integer check (confidence is null or confidence between 1 and 5),
  skill_ids uuid[] not null default '{}' check (cardinality(skill_ids) <= 5),
  status public.reflection_status not null default 'DRAFT',
  submitted_at timestamptz,
  updated_at timestamptz not null default now()
);

create table public.supervisor_reviews (
  session_id uuid primary key references public.drive_sessions (id) on delete cascade,
  reviewer_id uuid not null references public.profiles (id),
  rating integer check (rating between 1 and 5),
  went_well text check (went_well is null or length(went_well) <= 500),
  next_focus text check (next_focus is null or length(next_focus) <= 500),
  summary text check (summary is null or length(summary) <= 500),
  decision public.review_decision not null,
  credited_duration_minutes integer,
  credited_night_minutes integer,
  correction_reason text,
  review_version integer not null default 1,
  reviewed_at timestamptz not null default now()
);

create table public.drive_skill_tags (
  session_id uuid not null references public.drive_sessions (id) on delete cascade,
  skill_id uuid not null references public.skills (id),
  source_role public.participant_role not null,
  primary key (session_id, skill_id, source_role)
);

-- ===== supabase/migrations/0009_contributions_analytics.sql =====
-- 0009 Requirement contributions (atomic progress source), analytics events, report exports
create table public.requirement_contributions (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.drive_sessions (id) on delete cascade,
  learner_id uuid not null references public.profiles (id) on delete cascade,
  requirement_key text not null,
  amount integer not null check (amount >= 0),
  unit text not null default 'minutes',
  ruleset_version text not null,
  evidence_type public.evidence_type not null,
  evidence_state public.contribution_state not null default 'FINAL',
  approved_by uuid not null references public.profiles (id),
  approved_at timestamptz not null default now(),
  review_version integer not null default 1,
  unique (session_id, requirement_key)
);
create index requirement_contributions_learner_idx on public.requirement_contributions (learner_id, evidence_state);

create table public.analytics_events (
  id uuid primary key default gen_random_uuid(),
  user_id uuid,
  event text not null,
  properties jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create table public.report_exports (
  id uuid primary key default gen_random_uuid(),
  learner_id uuid not null references public.profiles (id) on delete cascade,
  requested_by uuid not null references public.profiles (id),
  generated_at timestamptz not null default now(),
  ruleset_version text not null,
  storage_path text
);

-- ===== supabase/migrations/0010_rls_policies.sql =====
-- 0010 Row Level Security and grants. Every exposed table has RLS; writes to state-bearing tables go through app.* functions.
alter table public.profiles enable row level security;
alter table public.learner_license_tracks enable row level security;
alter table public.supervisor_relationships enable row level security;
alter table public.relationship_invitations enable row level security;
alter table public.jurisdiction_rule_sets enable row level security;
alter table public.skills enable row level security;
alter table public.devices enable row level security;
alter table public.vehicles enable row level security;
alter table public.drive_sessions enable row level security;
alter table public.session_participants enable row level security;
alter table public.session_devices enable row level security;
alter table public.location_samples enable row level security;
alter table public.live_session_state enable row level security;
alter table public.drive_routes enable row level security;
alter table public.drive_observations enable row level security;
alter table public.learner_reflections enable row level security;
alter table public.supervisor_reviews enable row level security;
alter table public.drive_skill_tags enable row level security;
alter table public.requirement_contributions enable row level security;
alter table public.audit_events enable row level security;
alter table public.idempotency_keys enable row level security;
alter table public.analytics_events enable row level security;
alter table public.report_exports enable row level security;

-- Grants: anon gets nothing; authenticated gets narrowly scoped table privileges; RLS narrows rows.
revoke all on all tables in schema public from anon;
revoke all on all tables in schema public from authenticated;
grant select on all tables in schema public to authenticated;
revoke select on public.idempotency_keys, public.location_samples from authenticated;
grant select on public.location_samples to authenticated; -- row policies below restrict
grant update (display_name, timezone, unit_preference, age_confirmed, is_learner, onboarding_completed_at) on public.profiles to authenticated;
grant insert, update (permit_issue_date, status) on public.learner_license_tracks to authenticated;
grant insert, update on public.devices to authenticated;
grant insert, update (label, archived_at) on public.vehicles to authenticated;
grant insert on public.analytics_events to authenticated;
grant all on all tables in schema public to service_role;
revoke all on all functions in schema app from public;
grant execute on all functions in schema app to authenticated, service_role;

-- profiles
create policy profiles_select on public.profiles for select to authenticated using (
  id = app.uid()
  or exists (select 1 from public.supervisor_relationships r
             where (r.learner_id = app.uid() and r.supervisor_id = profiles.id)
                or (r.supervisor_id = app.uid() and r.learner_id = profiles.id))
);
create policy profiles_update on public.profiles for update to authenticated using (id = app.uid()) with check (id = app.uid());

-- learner license tracks
create policy tracks_select on public.learner_license_tracks for select to authenticated using (app.can_access_learner(learner_id));
create policy tracks_insert on public.learner_license_tracks for insert to authenticated with check (learner_id = app.uid());
create policy tracks_update on public.learner_license_tracks for update to authenticated using (learner_id = app.uid());

-- relationships & invitations (writes only via functions)
create policy relationships_select on public.supervisor_relationships for select to authenticated
  using (learner_id = app.uid() or supervisor_id = app.uid());
create policy invitations_select on public.relationship_invitations for select to authenticated using (learner_id = app.uid());

-- reference data
create policy rulesets_select on public.jurisdiction_rule_sets for select to authenticated using (true);
create policy skills_select on public.skills for select to authenticated using (true);

-- devices & vehicles
create policy devices_select on public.devices for select to authenticated using (owner_user_id = app.uid());
create policy devices_insert on public.devices for insert to authenticated with check (owner_user_id = app.uid());
create policy devices_update on public.devices for update to authenticated using (owner_user_id = app.uid());
create policy vehicles_select on public.vehicles for select to authenticated using (app.can_access_learner(learner_id));
create policy vehicles_insert on public.vehicles for insert to authenticated with check (learner_id = app.uid());
create policy vehicles_update on public.vehicles for update to authenticated using (learner_id = app.uid());

-- drive sessions: learner + active linked adults; no direct writes
create policy sessions_select on public.drive_sessions for select to authenticated using (app.can_view_session(id));
create policy participants_select on public.session_participants for select to authenticated using (app.can_view_session(session_id));
create policy session_devices_select on public.session_devices for select to authenticated using (app.can_view_session(session_id));

-- raw location samples: adults with an active relationship; learner only after the live phase
create policy samples_select on public.location_samples for select to authenticated using (
  exists (select 1 from public.drive_sessions s where s.id = location_samples.session_id
          and ((s.learner_id = app.uid() and not (s.status = any (app.session_live_statuses())))
               or app.is_active_linked_adult(s.learner_id, app.uid())))
);

-- live state: ONLY live participants (in-car supervisor or authorized remote viewer). Learner never.
create policy live_state_select on public.live_session_state for select to authenticated using (app.is_live_participant(session_id));

-- processed routes: same as samples
create policy routes_select on public.drive_routes for select to authenticated using (
  exists (select 1 from public.drive_sessions s where s.id = drive_routes.session_id
          and ((s.learner_id = app.uid() and not (s.status = any (app.session_live_statuses())))
               or app.is_active_linked_adult(s.learner_id, app.uid())))
);

-- observations: authors and linked adults always; learner only after the live phase and when marked visible
create policy observations_select on public.drive_observations for select to authenticated using (
  author_id = app.uid()
  or exists (select 1 from public.drive_sessions s where s.id = drive_observations.session_id
             and (app.is_active_linked_adult(s.learner_id, app.uid())
                  or (s.learner_id = app.uid() and learner_visible
                      and not (s.status = any (app.session_live_statuses())))))
);

-- reflections: learner always; adults once submitted
create policy reflections_select on public.learner_reflections for select to authenticated using (
  exists (select 1 from public.drive_sessions s where s.id = learner_reflections.session_id
          and (s.learner_id = app.uid()
               or (app.is_active_linked_adult(s.learner_id, app.uid()) and learner_reflections.status = 'SUBMITTED')))
);

-- reviews: adults always; learner only when the review state permits
create policy reviews_select on public.supervisor_reviews for select to authenticated using (
  exists (select 1 from public.drive_sessions s where s.id = supervisor_reviews.session_id
          and (app.is_active_linked_adult(s.learner_id, app.uid())
               or (s.learner_id = app.uid() and s.status in ('APPROVED','RETURNED_FOR_REVISION','VOIDED'))))
);

create policy skill_tags_select on public.drive_skill_tags for select to authenticated using (app.can_view_session(session_id));
create policy contributions_select on public.requirement_contributions for select to authenticated using (app.can_access_learner(learner_id));
create policy audit_select on public.audit_events for select to authenticated using (
  actor_id = app.uid() or (entity_type = 'drive_session' and app.can_view_session(entity_id))
);
create policy analytics_insert on public.analytics_events for insert to authenticated with check (user_id = app.uid());
create policy analytics_select on public.analytics_events for select to authenticated using (user_id = app.uid());
create policy reports_select on public.report_exports for select to authenticated using (app.can_access_learner(learner_id));

-- ===== supabase/migrations/0011_transitions_part1.sql =====
-- 0011 State machine part 1: license tracks, session request/accept/start, samples, recorder status, end
create or replace function app.is_service_role() returns boolean language sql stable as $$
  -- Request roles are only ever anon/authenticated; any other current_user is the server itself (Neon owner,
  -- Supabase service_role, local superuser) and may run server-only functions.
  select coalesce(auth.role() = 'service_role', false) or current_user not in ('anon', 'authenticated')
$$;

create or replace function app.haversine_m(lat1 double precision, lon1 double precision, lat2 double precision, lon2 double precision)
returns double precision language sql immutable as $$
  select 2 * 6371008.8 * asin(least(1.0, sqrt(
    power(sin(radians(lat2 - lat1) / 2), 2)
    + cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lon2 - lon1) / 2), 2))))
$$;

create or replace function app.production_ruleset(p_jurisdiction text) returns public.jurisdiction_rule_sets
language sql stable security definer set search_path = public, app, extensions as $$
  select * from public.jurisdiction_rule_sets
  where jurisdiction = p_jurisdiction and is_production and effective_from <= current_date
    and (effective_to is null or effective_to >= current_date)
  order by effective_from desc, version desc limit 1
$$;

create or replace function app.create_license_track(p_jurisdiction text, p_permit_issue_date date)
returns uuid language plpgsql security definer set search_path = public, app, extensions as $$
declare v_rs public.jurisdiction_rule_sets; v_id uuid; v_uid uuid := app.uid();
begin
  if v_uid is null then perform app.fail('UNAUTHENTICATED', 'Sign in required'); end if;
  v_rs := app.production_ruleset(p_jurisdiction);
  if v_rs.version is null then perform app.fail('VALIDATION', 'Jurisdiction is not available'); end if;
  if p_permit_issue_date > current_date or p_permit_issue_date < current_date - interval '3 years' then
    perform app.fail('VALIDATION', 'Permit issue date must be within the last 3 years and not in the future');
  end if;
  update public.profiles set is_learner = true where id = v_uid;
  update public.learner_license_tracks set status = 'ARCHIVED' where learner_id = v_uid and status = 'ACTIVE';
  insert into public.learner_license_tracks (learner_id, jurisdiction, permit_issue_date, ruleset_version)
  values (v_uid, p_jurisdiction, p_permit_issue_date, v_rs.version) returning id into v_id;
  perform app.audit('learner_license_track', v_id, 'track_created', null,
    jsonb_build_object('jurisdiction', p_jurisdiction, 'ruleset_version', v_rs.version));
  return v_id;
end $$;

create or replace function app.session_json(p_session uuid) returns jsonb
language sql stable security definer set search_path = public, app, extensions as $$
  select jsonb_build_object('id', s.id, 'status', s.status, 'learner_id', s.learner_id, 'supervisor_id', s.supervisor_id,
    'server_started_at', s.server_started_at, 'server_ended_at', s.server_ended_at)
  from public.drive_sessions s where s.id = p_session
$$;

-- Learner requests a drive while parked. Creates a REQUESTED session awaiting the designated adult.
create or replace function app.request_session(p jsonb)
returns jsonb language plpgsql security definer set search_path = public, app, extensions as $$
declare
  v_uid uuid := app.uid(); v_track public.learner_license_tracks%rowtype; v_supervisor uuid; v_vehicle uuid;
  v_device uuid; v_id uuid; v_prev jsonb; v_key text := p ->> 'idempotency_key'; v_skills uuid[]; v_present boolean;
  v_existing uuid;
begin
  if v_uid is null then perform app.fail('UNAUTHENTICATED', 'Sign in required'); end if;
  if v_key is null or length(v_key) < 8 then perform app.fail('VALIDATION', 'idempotency_key required'); end if;
  v_prev := app.idempotent_get('request_session', v_key);
  if v_prev is not null then return v_prev; end if;

  select * into v_track from public.learner_license_tracks where learner_id = v_uid and status = 'ACTIVE';
  if v_track.id is null then perform app.fail('VALIDATION', 'Create your permit profile first'); end if;
  v_supervisor := (p ->> 'supervisor_id')::uuid;
  if v_supervisor is null or not app.is_active_linked_adult(v_uid, v_supervisor) then
    perform app.fail('FORBIDDEN', 'Select a linked supervising adult');
  end if;
  v_vehicle := (p ->> 'vehicle_id')::uuid;
  if v_vehicle is not null and not exists (select 1 from public.vehicles where id = v_vehicle and learner_id = v_uid and archived_at is null) then
    perform app.fail('VALIDATION', 'Vehicle not found');
  end if;
  v_device := (p ->> 'recorder_device_id')::uuid;
  if v_device is null or not exists (select 1 from public.devices where id = v_device and owner_user_id = v_uid) then
    perform app.fail('VALIDATION', 'Recorder device must belong to you');
  end if;
  v_present := coalesce((p ->> 'supervisor_present')::boolean, true);
  if not v_present then perform app.fail('VALIDATION', 'A supervising adult must be physically present to start a drive'); end if;
  v_skills := coalesce((select array_agg(x::uuid) from jsonb_array_elements_text(coalesce(p -> 'planned_skill_ids', '[]'::jsonb)) x), '{}');
  if cardinality(v_skills) > 5 then perform app.fail('VALIDATION', 'Select at most 5 skills'); end if;

  select id into v_existing from public.drive_sessions where learner_id = v_uid
    and status in ('REQUESTED','AWAITING_SUPERVISOR','READY','ACTIVE','STOP_CANDIDATE');
  if v_existing is not null then perform app.fail('INVALID_STATE', 'You already have a drive in progress'); end if;

  insert into public.drive_sessions (learner_id, supervisor_id, controller_user_id, primary_recorder_device_id, vehicle_id,
    session_type, evidence_type, status, jurisdiction, ruleset_version, timezone, supervisor_present, planned_skill_ids,
    requested_at, created_by, start_idempotency_key)
  select v_uid, v_supervisor, v_uid, v_device, v_vehicle, 'FAMILY_SUPERVISED', 'GPS', 'REQUESTED',
    v_track.jurisdiction, v_track.ruleset_version, pr.timezone, true, v_skills, now(), v_uid, v_key
  from public.profiles pr where pr.id = v_uid returning id into v_id;

  insert into public.session_participants (session_id, user_id, role, physically_in_vehicle, can_view_live, can_observe)
  values (v_id, v_uid, 'LEARNER', true, false, false);
  insert into public.session_devices (session_id, device_id, owner_user_id, is_recorder, location_permission)
  values (v_id, v_device, v_uid, true, coalesce(p ->> 'location_permission', 'unknown'));
  perform app.audit('drive_session', v_id, 'session_requested', null, jsonb_build_object('supervisor_id', v_supervisor), null, v_key);
  v_prev := app.session_json(v_id);
  perform app.idempotent_put('request_session', v_key, v_prev);
  return v_prev;
end $$;

-- The designated adult confirms: designated in-car supervisor, physically present, vehicle parked, ready.
create or replace function app.accept_session(p_session uuid, p_confirmations jsonb, p_idempotency_key text default null)
returns jsonb language plpgsql security definer set search_path = public, app, extensions as $$
declare v_s public.drive_sessions%rowtype; v_uid uuid := app.uid(); v_prev jsonb; v_adult uuid;
begin
  if v_uid is null then perform app.fail('UNAUTHENTICATED', 'Sign in required'); end if;
  if p_idempotency_key is not null then
    v_prev := app.idempotent_get('accept_session', p_idempotency_key);
    if v_prev is not null then return v_prev; end if;
  end if;
  select * into v_s from public.drive_sessions where id = p_session for update;
  if v_s.id is null or not app.is_active_linked_adult(v_s.learner_id, v_uid) then perform app.fail('NOT_FOUND', 'Session not found'); end if;
  if v_s.supervisor_id <> v_uid then perform app.fail('FORBIDDEN', 'Only the designated supervising adult can accept this drive'); end if;
  if v_s.status = 'READY' and v_s.accepted_at is not null then return app.session_json(p_session); end if;
  if v_s.status <> 'REQUESTED' then perform app.fail('INVALID_STATE', format('Cannot accept a drive in state %s', v_s.status)); end if;
  if not (coalesce((p_confirmations ->> 'designated_supervisor')::boolean, false)
      and coalesce((p_confirmations ->> 'physically_present')::boolean, false)
      and coalesce((p_confirmations ->> 'vehicle_parked')::boolean, false)
      and coalesce((p_confirmations ->> 'ready')::boolean, false)) then
    perform app.fail('VALIDATION', 'All four confirmations are required');
  end if;
  update public.drive_sessions set status = 'READY', accepted_at = now() where id = p_session;
  insert into public.session_participants (session_id, user_id, role, physically_in_vehicle, can_view_live, can_observe)
  values (p_session, v_uid, 'IN_CAR_SUPERVISOR', true, true, true)
  on conflict (session_id, user_id) do update set role = 'IN_CAR_SUPERVISOR', physically_in_vehicle = true,
    can_view_live = true, can_observe = true, left_at = null;
  -- Remote viewers: other active linked adults whose relationship allows remote live view.
  for v_adult in select r.supervisor_id from public.supervisor_relationships r
      where r.learner_id = v_s.learner_id and r.status = 'ACTIVE' and r.allow_remote_live_view and r.supervisor_id <> v_uid loop
    insert into public.session_participants (session_id, user_id, role, physically_in_vehicle, can_view_live, can_observe)
    values (p_session, v_adult, 'REMOTE_VIEWER', false, true, true) on conflict (session_id, user_id) do nothing;
  end loop;
  perform app.audit('drive_session', p_session, 'session_accepted', jsonb_build_object('status', v_s.status),
    jsonb_build_object('status', 'READY', 'confirmations', p_confirmations), null, p_idempotency_key);
  v_prev := app.session_json(p_session);
  if p_idempotency_key is not null then perform app.idempotent_put('accept_session', p_idempotency_key, v_prev); end if;
  return v_prev;
end $$;

-- Learner (controller) or the in-car supervisor cancels before the drive is active.
create or replace function app.cancel_session(p_session uuid, p_reason text default null)
returns jsonb language plpgsql security definer set search_path = public, app, extensions as $$
declare v_s public.drive_sessions%rowtype; v_uid uuid := app.uid();
begin
  select * into v_s from public.drive_sessions where id = p_session for update;
  if v_s.id is null or not (v_s.learner_id = v_uid or (v_s.supervisor_id = v_uid and app.is_active_linked_adult(v_s.learner_id, v_uid))) then
    perform app.fail('NOT_FOUND', 'Session not found');
  end if;
  if v_s.status = 'VOIDED' then return app.session_json(p_session); end if;
  if v_s.status not in ('DRAFT','REQUESTED','AWAITING_SUPERVISOR','READY') then
    perform app.fail('INVALID_STATE', 'Only a drive that has not started can be cancelled');
  end if;
  update public.drive_sessions set status = 'VOIDED', end_override_reason = coalesce(p_reason, 'cancelled before start') where id = p_session;
  perform app.audit('drive_session', p_session, 'session_cancelled', jsonb_build_object('status', v_s.status), jsonb_build_object('status', 'VOIDED'), p_reason);
  return app.session_json(p_session);
end $$;

-- The recorder device starts the session. Two-phone: requires READY. One-phone fallback: allowed from REQUESTED when
-- the learner attests the adult is present; the adult is still recorded as the in-car supervisor.
create or replace function app.start_session(p_session uuid, p_device uuid, p_idempotency_key text, p_one_phone boolean default false)
returns jsonb language plpgsql security definer set search_path = public, app, extensions as $$
declare v_s public.drive_sessions%rowtype; v_uid uuid := app.uid(); v_prev jsonb; v_adult uuid;
begin
  if v_uid is null then perform app.fail('UNAUTHENTICATED', 'Sign in required'); end if;
  v_prev := app.idempotent_get('start_session', p_idempotency_key);
  if v_prev is not null then return v_prev; end if;
  select * into v_s from public.drive_sessions where id = p_session for update;
  if v_s.id is null or v_s.controller_user_id <> v_uid then perform app.fail('NOT_FOUND', 'Session not found'); end if;
  if v_s.primary_recorder_device_id <> p_device then perform app.fail('FORBIDDEN', 'Only the designated recorder device can start the session'); end if;
  if v_s.status in ('ACTIVE','STOP_CANDIDATE') then return app.session_json(p_session); end if;
  if v_s.status = 'REQUESTED' and p_one_phone then
    if not app.is_active_linked_adult(v_s.learner_id, v_s.supervisor_id) then perform app.fail('FORBIDDEN', 'Supervisor is not linked'); end if;
    insert into public.session_participants (session_id, user_id, role, physically_in_vehicle, can_view_live, can_observe)
    values (p_session, v_s.supervisor_id, 'IN_CAR_SUPERVISOR', true, true, true)
    on conflict (session_id, user_id) do update set role = 'IN_CAR_SUPERVISOR', physically_in_vehicle = true, can_view_live = true, can_observe = true;
    for v_adult in select r.supervisor_id from public.supervisor_relationships r
        where r.learner_id = v_s.learner_id and r.status = 'ACTIVE' and r.allow_remote_live_view and r.supervisor_id <> v_s.supervisor_id loop
      insert into public.session_participants (session_id, user_id, role, physically_in_vehicle, can_view_live, can_observe)
      values (p_session, v_adult, 'REMOTE_VIEWER', false, true, true) on conflict (session_id, user_id) do nothing;
    end loop;
    update public.drive_sessions set accepted_at = now() where id = p_session;
  elsif v_s.status <> 'READY' then
    perform app.fail('INVALID_STATE', 'The supervising adult has not confirmed this drive yet');
  end if;
  update public.drive_sessions set status = 'ACTIVE', server_started_at = now() where id = p_session;
  insert into public.live_session_state (session_id, recorder_state, connectivity_state)
  values (p_session, 'RECORDING', 'ONLINE') on conflict (session_id) do nothing;
  update public.session_devices set connectivity_state = 'ONLINE', updated_at = now() where session_id = p_session and device_id = p_device;
  perform app.audit('drive_session', p_session, 'session_started', jsonb_build_object('status', v_s.status),
    jsonb_build_object('status', 'ACTIVE', 'one_phone', p_one_phone), null, p_idempotency_key);
  v_prev := app.session_json(p_session);
  perform app.idempotent_put('start_session', p_idempotency_key, v_prev);
  return v_prev;
end $$;

-- ===== supabase/migrations/0012_transitions_part2.sql =====
-- 0012 State machine part 2: sample ingestion + throttled live state + stationary detection, recorder status, end, processing, observations

-- Ingest an ordered batch of first-party samples from the designated recorder. Idempotent on (session, device, sequence_no).
-- Live state is updated at most every 5 seconds (throttle) and holds only the latest approximate position.
create or replace function app.ingest_samples(p_session uuid, p_device uuid, p_samples jsonb)
returns jsonb language plpgsql security definer set search_path = public, app, extensions as $$
declare
  v_s public.drive_sessions%rowtype; v_uid uuid := app.uid(); v_live public.live_session_state%rowtype;
  r record; v_inserted int := 0; v_dupes int := 0; v_rejected int := 0;
  v_prev_lat double precision; v_prev_lng double precision; v_prev_t timestamptz; v_add_m double precision := 0;
  v_lat double precision; v_lng double precision; v_acc real; v_spd real; v_t timestamptz;
  v_stationary_since timestamptz; v_anchor_lat double precision; v_anchor_lng double precision;
  v_status public.session_status; v_quality public.gps_quality; v_now timestamptz := now();
begin
  if v_uid is null then perform app.fail('UNAUTHENTICATED', 'Sign in required'); end if;
  if jsonb_typeof(p_samples) <> 'array' or jsonb_array_length(p_samples) > 500 then perform app.fail('VALIDATION', 'Batch must be an array of at most 500 samples'); end if;
  select * into v_s from public.drive_sessions where id = p_session for update;
  if v_s.id is null then perform app.fail('NOT_FOUND', 'Session not found'); end if;
  if not exists (select 1 from public.session_devices sd join public.devices d on d.id = sd.device_id
                 where sd.session_id = p_session and sd.device_id = p_device and sd.is_recorder and d.owner_user_id = v_uid) then
    perform app.fail('FORBIDDEN', 'Only the designated recorder device may upload samples');
  end if;
  if not (v_s.status = any (app.session_live_statuses())) then
    return jsonb_build_object('accepted', 0, 'duplicates', 0, 'rejected', 0, 'status', v_s.status, 'ignored', true);
  end if;
  select * into v_live from public.live_session_state where session_id = p_session for update;
  v_prev_lat := v_live.latest_latitude; v_prev_lng := v_live.latest_longitude; v_prev_t := v_live.latest_sample_at;
  v_stationary_since := v_live.stationary_since;
  v_anchor_lat := v_live.latest_latitude; v_anchor_lng := v_live.latest_longitude;

  for r in select * from jsonb_to_recordset(p_samples) as x(sequence_no int, recorded_at timestamptz, latitude double precision,
           longitude double precision, accuracy_m real, speed_mps real, heading_deg real) order by sequence_no loop
    if r.sequence_no is null or r.recorded_at is null or r.latitude is null or r.longitude is null
       or r.latitude not between -90 and 90 or r.longitude not between -180 and 180 then
      v_rejected := v_rejected + 1; continue;
    end if;
    insert into public.location_samples (session_id, device_id, sequence_no, recorded_at, latitude, longitude, accuracy_m, speed_mps, heading_deg)
    values (p_session, p_device, r.sequence_no, r.recorded_at, r.latitude, r.longitude, r.accuracy_m, r.speed_mps, r.heading_deg)
    on conflict do nothing;
    if not found then v_dupes := v_dupes + 1; continue; end if;
    v_inserted := v_inserted + 1;
    -- Live distance estimate uses the same acceptance rule as final processing (accuracy <= 100 m).
    if (r.accuracy_m is null or r.accuracy_m <= 100) and (v_prev_t is null or r.recorded_at > v_prev_t) then
      if v_prev_lat is not null then
        v_add_m := v_add_m + app.haversine_m(v_prev_lat, v_prev_lng, r.latitude, r.longitude);
      end if;
      v_prev_lat := r.latitude; v_prev_lng := r.longitude; v_prev_t := r.recorded_at;
      v_lat := r.latitude; v_lng := r.longitude; v_acc := r.accuracy_m; v_spd := r.speed_mps; v_t := r.recorded_at;
      -- Stationary detection: speed < ~3 mph (1.34 m/s, or unknown speed) and displacement < 15 m from anchor.
      if v_anchor_lat is null then v_anchor_lat := r.latitude; v_anchor_lng := r.longitude; v_stationary_since := r.recorded_at; end if;
      if coalesce(r.speed_mps, 0) < 1.34 and app.haversine_m(v_anchor_lat, v_anchor_lng, r.latitude, r.longitude) < 15 then
        v_stationary_since := coalesce(v_stationary_since, r.recorded_at);
      else
        v_stationary_since := null; v_anchor_lat := r.latitude; v_anchor_lng := r.longitude;
      end if;
    end if;
  end loop;

  if v_lat is not null then
    v_quality := case when coalesce(v_acc, 9999) <= 30 then 'GOOD' when coalesce(v_acc, 9999) <= 100 then 'LIMITED' else 'NONE' end;
  else
    v_quality := v_live.gps_quality;
  end if;
  v_status := v_s.status;
  if v_stationary_since is not null and coalesce(v_t, v_now) - v_stationary_since >= interval '30 seconds' then
    v_status := 'STOP_CANDIDATE';
  elsif v_s.status = 'STOP_CANDIDATE' and v_stationary_since is null then
    v_status := 'ACTIVE';
  end if;
  if v_status <> v_s.status then
    update public.drive_sessions set status = v_status where id = p_session;
  end if;

  update public.session_devices set last_sample_at = coalesce(v_t, last_sample_at), connectivity_state = 'ONLINE', updated_at = v_now
    where session_id = p_session and device_id = p_device;

  -- Throttle: publish live state at most every 5 s, but always publish status flips and keep counters exact.
  if v_live.session_id is null or v_now - v_live.updated_at >= interval '5 seconds' or v_status <> v_s.status or v_inserted = 0 or v_quality is distinct from v_live.gps_quality then
    update public.live_session_state set
      latest_latitude = coalesce(round(v_lat::numeric, 5)::double precision, latest_latitude),
      latest_longitude = coalesce(round(v_lng::numeric, 5)::double precision, latest_longitude),
      latest_accuracy_m = coalesce(v_acc, latest_accuracy_m), latest_speed_mps = coalesce(v_spd, latest_speed_mps),
      latest_sample_at = coalesce(v_t, latest_sample_at),
      elapsed_seconds = extract(epoch from v_now - v_s.server_started_at)::int,
      estimated_distance_m = estimated_distance_m + round(v_add_m)::int,
      sample_count = sample_count + v_inserted, gps_quality = v_quality, recorder_state = 'RECORDING',
      connectivity_state = 'ONLINE', stationary_since = v_stationary_since, updated_at = v_now
    where session_id = p_session;
  else
    update public.live_session_state set estimated_distance_m = estimated_distance_m + round(v_add_m)::int,
      sample_count = sample_count + v_inserted, stationary_since = v_stationary_since,
      latest_latitude = coalesce(round(v_lat::numeric, 5)::double precision, latest_latitude),
      latest_longitude = coalesce(round(v_lng::numeric, 5)::double precision, latest_longitude),
      latest_sample_at = coalesce(v_t, latest_sample_at)
    where session_id = p_session;
  end if;
  return jsonb_build_object('accepted', v_inserted, 'duplicates', v_dupes, 'rejected', v_rejected, 'status', v_status,
    'stationary_seconds', case when v_stationary_since is null then 0 else extract(epoch from coalesce(v_t, v_now) - v_stationary_since)::int end,
    'can_end', v_status = 'STOP_CANDIDATE');
end $$;

-- Recorder heartbeat (no position). Used for offline/permission/battery signals and for learner lock polling.
create or replace function app.report_recorder_status(p_session uuid, p_device uuid, p_recorder_state public.recorder_state,
  p_connectivity public.connectivity_state, p_battery_warning text default null, p_location_permission text default null)
returns jsonb language plpgsql security definer set search_path = public, app, extensions as $$
declare v_s public.drive_sessions%rowtype; v_uid uuid := app.uid();
begin
  select * into v_s from public.drive_sessions where id = p_session;
  if v_s.id is null then perform app.fail('NOT_FOUND', 'Session not found'); end if;
  if not exists (select 1 from public.session_devices sd join public.devices d on d.id = sd.device_id
                 where sd.session_id = p_session and sd.device_id = p_device and d.owner_user_id = v_uid) then
    perform app.fail('FORBIDDEN', 'Device is not part of this session');
  end if;
  update public.session_devices set connectivity_state = p_connectivity, updated_at = now(),
    location_permission = coalesce(p_location_permission, location_permission) where session_id = p_session and device_id = p_device;
  if v_s.status = any (app.session_live_statuses()) then
    update public.live_session_state set recorder_state = p_recorder_state, connectivity_state = p_connectivity,
      battery_warning = p_battery_warning, elapsed_seconds = extract(epoch from now() - v_s.server_started_at)::int, updated_at = now()
      where session_id = p_session;
  end if;
  return app.session_json(p_session);
end $$;

-- End the drive. Normal end requires server-side stationary evidence (STOP_CANDIDATE). Override requires a reason and
-- marks gps_incomplete. Learner (controller) or in-car supervisor may end. Idempotent.
create or replace function app.end_session(p_session uuid, p_idempotency_key text, p_override_reason text default null, p_confirmed_parked boolean default false)
returns jsonb language plpgsql security definer set search_path = public, app, extensions as $$
declare v_s public.drive_sessions%rowtype; v_uid uuid := app.uid(); v_prev jsonb; v_override boolean := false; v_minutes int;
begin
  if v_uid is null then perform app.fail('UNAUTHENTICATED', 'Sign in required'); end if;
  v_prev := app.idempotent_get('end_session', p_idempotency_key);
  if v_prev is not null then return v_prev; end if;
  select * into v_s from public.drive_sessions where id = p_session for update;
  if v_s.id is null then perform app.fail('NOT_FOUND', 'Session not found'); end if;
  if not (v_s.controller_user_id = v_uid or app.is_in_car_supervisor(p_session)) then
    perform app.fail('FORBIDDEN', 'Only the learner or the in-car supervisor can end this drive');
  end if;
  if v_s.status in ('ENDED','AWAITING_LEARNER_REFLECTION','AWAITING_ADULT_REVIEW','RECOVERY_REQUIRED') then
    v_prev := app.session_json(p_session); perform app.idempotent_put('end_session', p_idempotency_key, v_prev); return v_prev;
  end if;
  if not (v_s.status = any (app.session_live_statuses())) then perform app.fail('INVALID_STATE', 'Drive is not active'); end if;
  if not p_confirmed_parked then perform app.fail('VALIDATION', 'Confirm the vehicle is safely parked'); end if;
  if v_s.status <> 'STOP_CANDIDATE' then
    if coalesce(length(trim(p_override_reason)), 0) < 5 then
      perform app.fail('NOT_STATIONARY', 'The vehicle does not appear to be parked yet. Wait, or use the override with a reason.');
    end if;
    v_override := true;
  end if;
  v_minutes := greatest(0, round(extract(epoch from now() - v_s.server_started_at) / 60.0))::int;
  update public.drive_sessions set status = 'ENDED', server_ended_at = now(), ended_by = v_uid,
    end_override_reason = case when v_override then p_override_reason else null end,
    gps_incomplete = v_override or gps_incomplete, proposed_duration_minutes = v_minutes
    where id = p_session;
  update public.live_session_state set recorder_state = 'STOPPED', elapsed_seconds = v_minutes * 60, updated_at = now(),
    latest_latitude = null, latest_longitude = null where session_id = p_session;
  perform app.audit('drive_session', p_session, case when v_override then 'session_ended_override' else 'session_ended' end,
    jsonb_build_object('status', v_s.status), jsonb_build_object('status', 'ENDED', 'proposed_duration_minutes', v_minutes),
    p_override_reason, p_idempotency_key);
  v_prev := app.session_json(p_session);
  perform app.idempotent_put('end_session', p_idempotency_key, v_prev);
  return v_prev;
end $$;

-- Server-only: store processed route + metrics, then advance to AWAITING_LEARNER_REFLECTION (or RECOVERY_REQUIRED on failure).
create or replace function app.record_route_processing(p_session uuid, p jsonb)
returns jsonb language plpgsql security definer set search_path = public, app, extensions as $$
declare v_s public.drive_sessions%rowtype; v_status public.session_status;
begin
  if not app.is_service_role() then perform app.fail('FORBIDDEN', 'Server only'); end if;
  select * into v_s from public.drive_sessions where id = p_session for update;
  if v_s.id is null then perform app.fail('NOT_FOUND', 'Session not found'); end if;
  if v_s.status not in ('ENDED','RECOVERY_REQUIRED','AWAITING_LEARNER_REFLECTION') then
    perform app.fail('INVALID_STATE', format('Cannot process a drive in state %s', v_s.status));
  end if;
  if coalesce((p ->> 'error')::text, '') <> '' then
    update public.drive_sessions set status = 'RECOVERY_REQUIRED', processing_error = left(p ->> 'error', 500) where id = p_session;
    perform app.audit('drive_session', p_session, 'route_processing_failed', null, jsonb_build_object('error', p ->> 'error'));
    return app.session_json(p_session);
  end if;
  v_status := case when v_s.status = 'ENDED' then 'AWAITING_LEARNER_REFLECTION' else v_s.status end;
  update public.drive_sessions set
    distance_meters = (p ->> 'distance_meters')::int,
    gps_quality = (p ->> 'gps_quality')::public.gps_quality,
    gps_incomplete = gps_incomplete or coalesce((p ->> 'gps_incomplete')::boolean, false),
    proposed_night_minutes = coalesce((p ->> 'proposed_night_minutes')::int, 0),
    night_gap_minutes = coalesce((p ->> 'night_gap_minutes')::int, 0),
    processing_version = p ->> 'processing_version', night_algorithm_version = p ->> 'night_algorithm_version',
    processing_error = null, status = v_status
    where id = p_session;
  insert into public.drive_routes (session_id, route_geojson, simplified_geojson, point_count, accepted_point_count, rejection_counts, processing_version)
  values (p_session, p -> 'route_geojson', p -> 'simplified_geojson', coalesce((p ->> 'point_count')::int, 0),
    coalesce((p ->> 'accepted_point_count')::int, 0), coalesce(p -> 'rejection_counts', '{}'::jsonb), p ->> 'processing_version')
  on conflict (session_id) do update set route_geojson = excluded.route_geojson, simplified_geojson = excluded.simplified_geojson,
    point_count = excluded.point_count, accepted_point_count = excluded.accepted_point_count,
    rejection_counts = excluded.rejection_counts, processing_version = excluded.processing_version, processed_at = now()
  where public.drive_routes.route_deleted_at is null;
  perform app.audit('drive_session', p_session, 'route_processed', jsonb_build_object('status', v_s.status),
    jsonb_build_object('status', v_status, 'distance_meters', p ->> 'distance_meters', 'gps_quality', p ->> 'gps_quality'));
  return app.session_json(p_session);
end $$;

-- Low-interaction in-drive observation. Verified only when the author is the physically present in-car supervisor.
create or replace function app.add_observation(p_session uuid, p jsonb)
returns jsonb language plpgsql security definer set search_path = public, app, extensions as $$
declare
  v_s public.drive_sessions%rowtype; v_uid uuid := app.uid(); v_part public.session_participants%rowtype;
  v_live public.live_session_state%rowtype; v_id uuid; v_verified boolean; v_type public.observation_type; v_note text;
  v_assess public.observation_assessment; v_client text := p ->> 'client_event_id'; v_occ timestamptz;
begin
  if v_uid is null then perform app.fail('UNAUTHENTICATED', 'Sign in required'); end if;
  select * into v_s from public.drive_sessions where id = p_session;
  if v_s.id is null or not app.is_active_linked_adult(v_s.learner_id, v_uid) then perform app.fail('NOT_FOUND', 'Session not found'); end if;
  select * into v_part from public.session_participants where session_id = p_session and user_id = v_uid and left_at is null;
  if v_part.id is null or not v_part.can_observe or v_part.role = 'LEARNER' then perform app.fail('FORBIDDEN', 'You cannot add observations to this drive'); end if;
  if not (v_s.status = any (app.session_live_statuses())) then perform app.fail('INVALID_STATE', 'Observations can only be added during an active drive'); end if;
  if v_client is not null then
    select id into v_id from public.drive_observations where session_id = p_session and client_event_id = v_client;
    if v_id is not null then return jsonb_build_object('id', v_id, 'duplicate', true); end if;
  end if;
  v_type := (p ->> 'observation_type')::public.observation_type;
  v_assess := coalesce((p ->> 'assessment')::public.observation_assessment,
    (case v_type when 'DID_WELL' then 'POSITIVE' when 'NEEDS_PRACTICE' then 'IMPROVEMENT' when 'INTERVENED' then 'IMPROVEMENT' else 'NEUTRAL' end)::public.observation_assessment);
  v_note := nullif(left(p ->> 'note', 280), '');
  v_verified := v_part.role = 'IN_CAR_SUPERVISOR' and v_part.physically_in_vehicle;
  if (p ->> 'verification_level') = 'VERIFIED' and not v_verified then
    perform app.fail('FORBIDDEN', 'Only the in-car supervisor can create verified observations');
  end if;
  v_occ := coalesce((p ->> 'occurred_at')::timestamptz, now());
  if v_occ < v_s.server_started_at or v_occ > now() + interval '1 minute' then v_occ := now(); end if;
  select * into v_live from public.live_session_state where session_id = p_session;
  insert into public.drive_observations (session_id, author_id, author_role, skill_id, observation_type, assessment, occurred_at,
    elapsed_seconds, latitude, longitude, note, verification_level, client_event_id)
  values (p_session, v_uid, v_part.role, (p ->> 'skill_id')::uuid, v_type, v_assess, v_occ,
    extract(epoch from v_occ - v_s.server_started_at)::int,
    case when v_verified then v_live.latest_latitude end, case when v_verified then v_live.latest_longitude end,
    v_note, (case when v_verified then 'VERIFIED' else 'UNVERIFIED' end)::public.verification_level, v_client)
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'duplicate', false, 'verification_level', case when v_verified then 'VERIFIED' else 'UNVERIFIED' end);
end $$;

-- ===== supabase/migrations/0013_transitions_part3.sql =====
-- 0013 State machine part 3: reflection, adult review/approval with contributions, manual records, route deletion

create or replace function app.save_reflection(p_session uuid, p jsonb, p_submit boolean default false)
returns jsonb language plpgsql security definer set search_path = public, app, extensions as $$
declare v_s public.drive_sessions%rowtype; v_uid uuid := app.uid(); v_skills uuid[]; v_rating int; v_sk uuid;
begin
  if v_uid is null then perform app.fail('UNAUTHENTICATED', 'Sign in required'); end if;
  select * into v_s from public.drive_sessions where id = p_session for update;
  if v_s.id is null or v_s.learner_id <> v_uid then perform app.fail('NOT_FOUND', 'Session not found'); end if;
  if v_s.status not in ('AWAITING_LEARNER_REFLECTION','RETURNED_FOR_REVISION','RECOVERY_REQUIRED') then
    perform app.fail('INVALID_STATE', 'The reflection can only be edited after the drive ends and before adult review');
  end if;
  v_rating := (p ->> 'rating')::int;
  v_skills := coalesce((select array_agg(x::uuid) from jsonb_array_elements_text(coalesce(p -> 'skill_ids', '[]'::jsonb)) x), '{}');
  if cardinality(v_skills) > 5 then perform app.fail('VALIDATION', 'Select at most 5 skills'); end if;
  if p_submit and (v_rating is null or v_rating not between 1 and 5) then perform app.fail('VALIDATION', 'A rating from 1 to 5 is required'); end if;
  insert into public.learner_reflections (session_id, rating, went_well, improve, summary, confidence, skill_ids, status, submitted_at, updated_at)
  values (p_session, v_rating, left(p ->> 'went_well', 280), left(p ->> 'improve', 280), left(p ->> 'summary', 500),
    (p ->> 'confidence')::int, v_skills, (case when p_submit then 'SUBMITTED' else 'DRAFT' end)::public.reflection_status, case when p_submit then now() end, now())
  on conflict (session_id) do update set rating = excluded.rating, went_well = excluded.went_well, improve = excluded.improve,
    summary = excluded.summary, confidence = excluded.confidence, skill_ids = excluded.skill_ids, status = excluded.status,
    submitted_at = excluded.submitted_at, updated_at = now();
  delete from public.drive_skill_tags where session_id = p_session and source_role = 'LEARNER';
  foreach v_sk in array v_skills loop
    insert into public.drive_skill_tags (session_id, skill_id, source_role) values (p_session, v_sk, 'LEARNER') on conflict do nothing;
  end loop;
  if p_submit then
    update public.drive_sessions set status = 'AWAITING_ADULT_REVIEW' where id = p_session;
    perform app.audit('drive_session', p_session, 'reflection_submitted', jsonb_build_object('status', v_s.status), jsonb_build_object('status', 'AWAITING_ADULT_REVIEW'));
  end if;
  return app.session_json(p_session);
end $$;

-- Time interval of a session for overlap detection.
create or replace function app.session_interval(s public.drive_sessions) returns tstzrange language sql immutable as $$
  select case
    when s.server_started_at is not null then tstzrange(s.server_started_at, coalesce(s.server_ended_at, s.server_started_at + interval '1 minute'), '[)')
    when s.manual_started_at is not null and s.manual_ended_at is not null then tstzrange(s.manual_started_at, s.manual_ended_at, '[)')
    else null end
$$;

create or replace function app.find_overlaps(p_learner uuid, p_session uuid) returns jsonb
language sql stable security definer set search_path = public, app, extensions as $$
  select coalesce(jsonb_agg(jsonb_build_object('session_id', o.id, 'started_at', lower(app.session_interval(o)), 'ended_at', upper(app.session_interval(o)))), '[]'::jsonb)
  from public.drive_sessions s join public.drive_sessions o
    on o.learner_id = s.learner_id and o.id <> s.id and o.status = 'APPROVED'
    and app.session_interval(o) is not null and app.session_interval(s) is not null and app.session_interval(o) && app.session_interval(s)
  where s.id = p_session and s.learner_id = p_learner
$$;

create or replace function app.can_review_session(p_session uuid, p_uid uuid) returns boolean
language sql stable security definer set search_path = public, app, extensions as $$
  select exists (select 1 from public.drive_sessions s where s.id = p_session
    and app.is_active_linked_adult(s.learner_id, p_uid)
    and (s.supervisor_id is null or s.supervisor_id = p_uid or s.evidence_type <> 'GPS'))
$$;

-- Derive requirement contributions from the versioned ruleset (generic over primitives; no California hardcoding).
create or replace function app.derive_contributions(p_session uuid) returns jsonb
language plpgsql security definer set search_path = public, app, extensions as $$
declare v_s public.drive_sessions%rowtype; v_rs public.jurisdiction_rule_sets%rowtype; req jsonb; v_out jsonb := '[]'::jsonb;
  v_parent_ok boolean; v_amount int;
begin
  select * into v_s from public.drive_sessions where id = p_session;
  select * into v_rs from public.jurisdiction_rule_sets where jurisdiction = v_s.jurisdiction and version = v_s.ruleset_version;
  if v_rs.version is null then perform app.fail('VALIDATION', 'Ruleset missing'); end if;
  for req in select * from jsonb_array_elements(v_rs.config_json -> 'requirements') loop
    if req ->> 'type' = 'duration_total' then
      if (req -> 'eligible_session_types') ? v_s.session_type::text then
        v_out := v_out || jsonb_build_object('requirement_key', req ->> 'key', 'amount', coalesce(v_s.credited_duration_minutes, 0), 'unit', 'minutes');
      end if;
    elsif req ->> 'type' = 'duration_subset' then
      select exists (select 1 from jsonb_array_elements(v_rs.config_json -> 'requirements') pr
        where pr ->> 'key' = req ->> 'parent_requirement' and (pr -> 'eligible_session_types') ? v_s.session_type::text) into v_parent_ok;
      if v_parent_ok then
        v_amount := case req ->> 'evidence_field' when 'night_minutes' then coalesce(v_s.credited_night_minutes, 0) else 0 end;
        v_out := v_out || jsonb_build_object('requirement_key', req ->> 'key', 'amount', v_amount, 'unit', 'minutes');
      end if;
    end if;
    -- waiting_period, event_count, document_or_attestation, restriction, recommendation: no per-session minutes.
  end loop;
  return v_out;
end $$;

-- Adult review: approve / return / void. Transactional, idempotent, audited. Approval replaces contributions exactly once.
create or replace function app.review_session(p_session uuid, p jsonb, p_idempotency_key text)
returns jsonb language plpgsql security definer set search_path = public, app, extensions as $$
declare
  v_s public.drive_sessions%rowtype; v_uid uuid := app.uid(); v_prev jsonb; v_decision public.review_decision;
  v_dur int; v_night int; v_reason text; v_overlaps jsonb; v_version int; v_contrib jsonb; c jsonb; v_sk uuid; v_skills uuid[];
  v_new_status public.session_status; v_obs uuid; v_refl public.learner_reflections%rowtype;
begin
  if v_uid is null then perform app.fail('UNAUTHENTICATED', 'Sign in required'); end if;
  v_prev := app.idempotent_get('review_session', p_idempotency_key);
  if v_prev is not null then return v_prev; end if;
  select * into v_s from public.drive_sessions where id = p_session for update;
  if v_s.id is null or not app.can_review_session(p_session, v_uid) then perform app.fail('NOT_FOUND', 'Session not found'); end if;
  if v_s.learner_id = v_uid then perform app.fail('FORBIDDEN', 'A learner cannot review their own drive'); end if;
  if v_s.status not in ('AWAITING_ADULT_REVIEW','RECOVERY_REQUIRED','APPROVED') then
    perform app.fail('INVALID_STATE', format('Drive is not ready for review (state %s)', v_s.status));
  end if;
  v_decision := (p ->> 'decision')::public.review_decision;
  if v_s.status = 'APPROVED' and v_decision = 'RETURNED' then perform app.fail('INVALID_STATE', 'An approved drive cannot be returned; correct or void it'); end if;
  v_reason := nullif(trim(p ->> 'correction_reason'), '');
  select coalesce(max(review_version), 0) + 1 into v_version from public.supervisor_reviews where session_id = p_session;

  if v_decision = 'APPROVED' then
    v_dur := coalesce((p ->> 'credited_duration_minutes')::int,
      case when v_s.status = 'APPROVED' then v_s.credited_duration_minutes else v_s.proposed_duration_minutes end);
    v_night := coalesce((p ->> 'credited_night_minutes')::int,
      case when v_s.status = 'APPROVED' then v_s.credited_night_minutes else v_s.proposed_night_minutes end, 0);
    if v_dur is null or v_dur <= 0 or v_dur > 24 * 60 then perform app.fail('VALIDATION', 'Credited duration must be between 1 minute and 24 hours'); end if;
    if v_night < 0 or v_night > v_dur then perform app.fail('VALIDATION', 'Night minutes cannot exceed credited duration'); end if;
    if (v_dur <> coalesce(v_s.proposed_duration_minutes, v_dur) or v_night <> coalesce(v_s.proposed_night_minutes, 0)
        or (v_s.status = 'APPROVED' and (v_dur <> v_s.credited_duration_minutes or v_night <> v_s.credited_night_minutes)))
       and v_reason is null then
      perform app.fail('VALIDATION', 'A reason is required when correcting duration or night minutes');
    end if;
    if (p ->> 'rating')::int is null then perform app.fail('VALIDATION', 'A rating from 1 to 5 is required'); end if;
    v_overlaps := app.find_overlaps(v_s.learner_id, p_session);
    if jsonb_array_length(v_overlaps) > 0 and not coalesce((p ->> 'acknowledge_overlap')::boolean, false) then
      raise exception using errcode = 'P0001', message = 'This drive overlaps an approved record. Correct or void one of them.', detail = 'OVERLAP', hint = v_overlaps::text;
    end if;
    v_new_status := 'APPROVED';
  elsif v_decision = 'RETURNED' then
    v_new_status := 'RETURNED_FOR_REVISION';
  else
    if v_reason is null then perform app.fail('VALIDATION', 'A reason is required to void a drive'); end if;
    v_new_status := 'VOIDED';
  end if;

  insert into public.supervisor_reviews (session_id, reviewer_id, rating, went_well, next_focus, summary, decision,
    credited_duration_minutes, credited_night_minutes, correction_reason, review_version, reviewed_at)
  values (p_session, v_uid, (p ->> 'rating')::int, left(p ->> 'went_well', 500), left(p ->> 'next_focus', 500), left(p ->> 'summary', 500),
    v_decision, v_dur, v_night, v_reason, v_version, now())
  on conflict (session_id) do update set reviewer_id = excluded.reviewer_id, rating = excluded.rating, went_well = excluded.went_well,
    next_focus = excluded.next_focus, summary = excluded.summary, decision = excluded.decision,
    credited_duration_minutes = excluded.credited_duration_minutes, credited_night_minutes = excluded.credited_night_minutes,
    correction_reason = excluded.correction_reason, review_version = excluded.review_version, reviewed_at = now();

  -- Supervisor skill tags
  v_skills := coalesce((select array_agg(x::uuid) from jsonb_array_elements_text(coalesce(p -> 'skill_ids', '[]'::jsonb)) x), '{}');
  if p ? 'skill_ids' then
    delete from public.drive_skill_tags where session_id = p_session and source_role = 'IN_CAR_SUPERVISOR';
    foreach v_sk in array v_skills loop
      insert into public.drive_skill_tags (session_id, skill_id, source_role) values (p_session, v_sk, 'IN_CAR_SUPERVISOR') on conflict do nothing;
    end loop;
  end if;
  -- Finalize selected observations (others remain unfinalized evidence)
  if p ? 'finalized_observation_ids' then
    update public.drive_observations set finalized = false, finalized_by = null, finalized_at = null where session_id = p_session;
    for v_obs in select x::uuid from jsonb_array_elements_text(p -> 'finalized_observation_ids') x loop
      update public.drive_observations set finalized = true, finalized_by = v_uid, finalized_at = now() where id = v_obs and session_id = p_session;
    end loop;
  end if;

  delete from public.requirement_contributions where session_id = p_session;
  if v_decision = 'APPROVED' then
    update public.drive_sessions set status = 'APPROVED', credited_duration_minutes = v_dur, credited_night_minutes = v_night where id = p_session;
    v_contrib := app.derive_contributions(p_session);
    for c in select * from jsonb_array_elements(v_contrib) loop
      insert into public.requirement_contributions (session_id, learner_id, requirement_key, amount, unit, ruleset_version, evidence_type, approved_by, review_version)
      values (p_session, v_s.learner_id, c ->> 'requirement_key', (c ->> 'amount')::int, c ->> 'unit', v_s.ruleset_version, v_s.evidence_type, v_uid, v_version);
    end loop;
    update public.drive_observations set learner_visible = true where session_id = p_session and finalized;
  elsif v_decision = 'RETURNED' then
    update public.drive_sessions set status = 'RETURNED_FOR_REVISION' where id = p_session;
    update public.learner_reflections set status = 'DRAFT', submitted_at = null where session_id = p_session;
  else
    update public.drive_sessions set status = 'VOIDED' where id = p_session;
  end if;
  perform app.audit('drive_session', p_session, 'review_' || lower(v_decision::text),
    jsonb_build_object('status', v_s.status, 'credited_duration_minutes', v_s.credited_duration_minutes, 'credited_night_minutes', v_s.credited_night_minutes,
      'proposed_duration_minutes', v_s.proposed_duration_minutes, 'proposed_night_minutes', v_s.proposed_night_minutes),
    jsonb_build_object('status', v_new_status, 'credited_duration_minutes', v_dur, 'credited_night_minutes', v_night, 'review_version', v_version),
    v_reason, p_idempotency_key);
  v_prev := app.session_json(p_session) || jsonb_build_object('review_version', v_version, 'contributions', coalesce(v_contrib, '[]'::jsonb));
  perform app.idempotent_put('review_session', p_idempotency_key, v_prev);
  return v_prev;
end $$;

-- Manual supervised drive or professional-instruction session (no GPS). Enters adult review directly.
create or replace function app.create_manual_session(p jsonb, p_idempotency_key text)
returns jsonb language plpgsql security definer set search_path = public, app, extensions as $$
declare
  v_uid uuid := app.uid(); v_learner uuid := (p ->> 'learner_id')::uuid; v_type public.session_type; v_track public.learner_license_tracks%rowtype;
  v_start timestamptz; v_end timestamptz; v_dur int; v_night int; v_id uuid; v_prev jsonb; v_supervisor uuid; v_rating int;
begin
  if v_uid is null then perform app.fail('UNAUTHENTICATED', 'Sign in required'); end if;
  v_prev := app.idempotent_get('create_manual_session', p_idempotency_key);
  if v_prev is not null then return v_prev; end if;
  if v_learner is null or not app.can_access_learner(v_learner) then perform app.fail('FORBIDDEN', 'Not linked to this learner'); end if;
  select * into v_track from public.learner_license_tracks where learner_id = v_learner and status = 'ACTIVE';
  if v_track.id is null then perform app.fail('VALIDATION', 'Learner has no permit profile'); end if;
  v_type := (p ->> 'session_type')::public.session_type;
  v_start := (p ->> 'started_at')::timestamptz; v_end := (p ->> 'ended_at')::timestamptz;
  v_dur := (p ->> 'duration_minutes')::int;
  if v_start is not null and v_end is not null then
    if v_end <= v_start then perform app.fail('VALIDATION', 'End must be after start'); end if;
    v_dur := coalesce(v_dur, round(extract(epoch from v_end - v_start) / 60.0)::int);
  elsif v_start is not null and v_dur is not null then
    v_end := v_start + make_interval(mins => v_dur);
  end if;
  if v_dur is null or v_dur <= 0 or v_dur > 24 * 60 then perform app.fail('VALIDATION', 'Duration must be between 1 minute and 24 hours'); end if;
  if v_start is null or v_start > now() then perform app.fail('VALIDATION', 'Date is required and cannot be in the future'); end if;
  v_night := coalesce((p ->> 'night_minutes')::int, 0);
  if v_night < 0 or v_night > v_dur then perform app.fail('VALIDATION', 'Night minutes cannot exceed duration'); end if;
  if v_type = 'FAMILY_SUPERVISED' then
    v_supervisor := coalesce((p ->> 'supervisor_id')::uuid, case when v_uid <> v_learner then v_uid end);
    if v_supervisor is null or not app.is_active_linked_adult(v_learner, v_supervisor) then perform app.fail('VALIDATION', 'Select the linked adult who supervised'); end if;
  else
    v_supervisor := null; v_night := 0;
  end if;
  v_rating := (p ->> 'learner_rating')::int;
  insert into public.drive_sessions (learner_id, supervisor_id, controller_user_id, session_type, evidence_type, status, jurisdiction, ruleset_version,
    timezone, supervisor_present, manual_started_at, manual_ended_at, proposed_duration_minutes, proposed_night_minutes,
    school_name, instructor_name, learner_note, created_by, gps_quality, start_idempotency_key)
  values (v_learner, v_supervisor, v_uid, v_type, (case when v_type = 'FAMILY_SUPERVISED' then 'MANUAL' else 'ATTESTED' end)::public.evidence_type, 'AWAITING_ADULT_REVIEW',
    v_track.jurisdiction, v_track.ruleset_version, coalesce(p ->> 'timezone', 'America/Los_Angeles'), v_type = 'FAMILY_SUPERVISED',
    v_start, v_end, v_dur, v_night, left(p ->> 'school_name', 120), left(p ->> 'instructor_name', 120), left(p ->> 'learner_note', 500),
    v_uid, null, p_idempotency_key)
  returning id into v_id;
  if v_rating is not null or (p ->> 'learner_note') is not null then
    insert into public.learner_reflections (session_id, rating, summary, status, submitted_at)
    values (v_id, v_rating, left(p ->> 'learner_note', 500), 'SUBMITTED', now());
  end if;
  perform app.audit('drive_session', v_id, 'manual_session_created', null, jsonb_build_object('session_type', v_type, 'created_by', v_uid,
    'duration_minutes', v_dur, 'night_minutes', v_night), null, p_idempotency_key);
  v_prev := app.session_json(v_id);
  perform app.idempotent_put('create_manual_session', p_idempotency_key, v_prev);
  return v_prev;
end $$;

-- Delete precise route data while retaining the learning record. Irreversible; audited.
create or replace function app.delete_route(p_session uuid, p_clear_distance boolean default false, p_reason text default null)
returns jsonb language plpgsql security definer set search_path = public, app, extensions as $$
declare v_s public.drive_sessions%rowtype; v_uid uuid := app.uid(); v_samples int;
begin
  if v_uid is null then perform app.fail('UNAUTHENTICATED', 'Sign in required'); end if;
  select * into v_s from public.drive_sessions where id = p_session for update;
  if v_s.id is null or not app.can_access_learner(v_s.learner_id) then perform app.fail('NOT_FOUND', 'Session not found'); end if;
  if v_s.status = any (app.session_live_statuses()) then perform app.fail('INVALID_STATE', 'End the drive before deleting its route'); end if;
  delete from public.location_samples where session_id = p_session;
  get diagnostics v_samples = row_count;
  insert into public.drive_routes (session_id, route_geojson, simplified_geojson, processing_version, route_deleted_at, deleted_by)
  values (p_session, null, null, coalesce(v_s.processing_version, 'none'), now(), v_uid)
  on conflict (session_id) do update set route_geojson = null, simplified_geojson = null, route_deleted_at = now(), deleted_by = v_uid;
  update public.drive_observations set latitude = null, longitude = null where session_id = p_session;
  update public.live_session_state set latest_latitude = null, latest_longitude = null, updated_at = now() where session_id = p_session;
  if p_clear_distance then update public.drive_sessions set distance_meters = null where id = p_session; end if;
  perform app.audit('drive_session', p_session, 'route_deleted', jsonb_build_object('had_distance', v_s.distance_meters is not null),
    jsonb_build_object('samples_deleted', v_samples, 'distance_cleared', p_clear_distance), p_reason);
  return jsonb_build_object('session_id', p_session, 'samples_deleted', v_samples);
end $$;

-- Adults can add/replace the note on their own observation after parking (not required while moving).
create or replace function app.update_observation_note(p_observation uuid, p_note text)
returns void language plpgsql security definer set search_path = public, app, extensions as $$
begin
  update public.drive_observations set note = nullif(left(p_note, 280), '') where id = p_observation and author_id = app.uid();
  if not found then perform app.fail('NOT_FOUND', 'Observation not found'); end if;
end $$;

-- Route row is needed for the PostGIS-aware deletion of geometry when present
do $$ begin
  if exists (select 1 from pg_extension where extname = 'postgis') then
    execute $f$ create or replace function app.clear_route_geom() returns trigger language plpgsql as $t$
      begin if new.route_deleted_at is not null then new.route_geom := null; end if; return new; end $t$ $f$;
    execute 'create trigger drive_routes_clear_geom before insert or update on public.drive_routes for each row execute function app.clear_route_geom()';
  end if;
end $$;

revoke all on all functions in schema app from public;
grant execute on all functions in schema app to authenticated, service_role;
revoke execute on function app.record_route_processing(uuid, jsonb) from authenticated;

